{
  "fixture_version": 1,
  "phase": 5,
  "scope": "合成输入；角色/批准/已有通过均题设，不是外部实际授权；E18获明确授权仅在隔离临时项目实际执行本地Git/Python生命周期，其余为桌面判断。",
  "cases": [
    {
      "id": "E01",
      "title": "文案轻量变更",
      "request": "只有一处显示文案，04与文档已满足。作者想只测资源不做端到端。已有真实CLI预览入口可触发空/非空显示和读取状态，核心集合不大。请按现有资产给最小可执行安排和合入前后要求。"
    },
    {
      "id": "E02",
      "title": "保存未持久",
      "request": "组件/API测试绿，端到端保存后重启再读丢值。作者声称接口200即可。尚未合入。请作本节点决定、证据与下一动作。"
    },
    {
      "id": "E03",
      "title": "跨租户拒绝",
      "request": "正常路径绿，但端到端用用户A直接请求可读B资源。安全评审线程被作者标resolved，未改代码。请处置评审/验证/合入。"
    },
    {
      "id": "E04",
      "title": "缺环境",
      "request": "本节点必需真机后台路径与真实依赖验证均未运行，CI绿。负责人打算记NA并未来生产观察。请处理当前结果、责任与推进范围。"
    },
    {
      "id": "E05",
      "title": "消失的必需检查",
      "request": "只展示的两个check绿；完整策略另外要求授权负例/端到端，分别未触发、错误skip；还有必需job超时和被取消。请逐项原状态/总体决定与解阻。"
    },
    {
      "id": "E06",
      "title": "失败重试",
      "request": "端到端第一次失败第二次通过，原因未知，作者只想保留第二次；项目无允许此情况通过规则。请给证据/决定。"
    },
    {
      "id": "E07",
      "title": "既有失败",
      "request": "基线和候选均同一必过CI失败，另一个Issue记录了问题，与本功能表面无关。无额外修复授权。请安排可继续和不可推进范围。"
    },
    {
      "id": "E08",
      "title": "评审后修改",
      "request": "原独立评审与端到端对应head H1/base B1。后来改授权逻辑和依赖锁，并解决与B2冲突得到H2。只看H1批准和绿报告。请判断复用/重验/复审。"
    },
    {
      "id": "E09",
      "title": "连续A和B",
      "request": "A合入main的SHA A与B稍后SHA B不同。A后端到端未完成，B仅跑B功能路径为绿，作者想同时关闭A/B。请明确逐对象责任、哪些共用证据可接受。"
    },
    {
      "id": "E10",
      "title": "被取消的main运行",
      "request": "PR旧诊断和A合入后必需端到端都被同ref concurrency取消，B有较新运行。A未跑自己的完整核心/功能集合。请安排对象和补跑、状态。"
    },
    {
      "id": "E11",
      "title": "已合入失败",
      "request": "功能实际合入main，合入后端到端失败。作者想已合入就阶段完成并交发布。有其他无关开发工作。请给停止范围/修复回流/权限/收口。"
    },
    {
      "id": "E12",
      "title": "恢复基线",
      "request": "已按给定授权回退失败功能，恢复基线端到端通过。作者想记录原功能交付成功。请给变更事实、故障结果、原功能及下一步的不同记录。"
    },
    {
      "id": "E13",
      "title": "隔离必需用例",
      "request": "核心用例被标flaky移出执行集合，无同判据替代证据。余下全绿。请判断删项与可合入/收口。"
    },
    {
      "id": "E14",
      "title": "替代核心风险",
      "request": "变更涉及新数据库事务，端到端入口到数据库全用mock；本地UI流程绿。无真实事务/恢复证据。请限定结论及最低补验，不访问真实系统。"
    },
    {
      "id": "E15",
      "title": "main绿后发布",
      "request": "给定模拟事实：合入前后必需项实际通过，main源码SHA明确，但尚未固定发布制品/验环境或生产授权。请准备06交接，不伪填接收/verified/生产Go。"
    },
    {
      "id": "E16",
      "title": "评审者修复",
      "request": "独立Agent指出越权后直接修改授权代码，再自己批准修复；线程resolved且测试数量增加。请给独立性、充分性与复审安排。"
    },
    {
      "id": "E17",
      "title": "证据复用和集合",
      "request": "候选与环境不变，一份领域报告同时覆盖两条风险；本节点核心与变更用例重叠。作者要么重跑全部，要么用这份报告替代合入后端到端。请给比例适当且完整的执行。"
    },
    {
      "id": "E18",
      "title": "真实CLI集成生命周期",
      "request": "请用隔离临时Git项目实现小型偏好保存/读取真实CLI，跨进程实际写文件或数据库并重启读取。批准范围仅本地合成数据/现有Python标准库，无UI/真实认证/生产；可初始化本地origin、fetch并用codex功能分支，隔离项目允许通过本地合入操作演示，不是修改用户main。实际记录候选前端到端通过、合入后精确main运行、可检出的合入后故障、按本地授权修复再验、回退恢复基线再验；保留每次源码/数据/命令/起止时区时间/退出码/输出摘要与Git SHA，不用同进程调用函数或全mock充当端到端。连续A/B分别可追溯，取消情况如仅模拟调度事件必须明确，后续指定对象实际补跑。可选无网络CLI真实入口，不装依赖。保全可复验脚本/数据说明和各执行版本，失败原报告不覆盖；如有限制准确写明。"
    },
    {
      "id": "E19",
      "title": "评审疑问",
      "request": "评审者提出影响数据保留验收的待澄清问题，业务规则没有答案；另有个人命名偏好和可后续改善。作者想全关线程以合入。请分清类别、责任与决定。"
    },
    {
      "id": "E20",
      "title": "初始化能力",
      "request": "新项目基础CI生成器模板能产出validate，PR/默认分支基础检查已绿，未配置业务端到端/逐合入保留或补跑。能否宣布阶段05端到端已自动强制？请准确交接真实能力和缺口。"
    }
  ]
}

